        CREATE TABLE temp_prod AS SELECT PROCOD FROM PRODUTO WHERE procod >= 999999 AND proenvbal = 'N' ORDER BY procod ;

        DROP TRIGGER estoque_movimentacao_trigger ON public.estoque_movimentacao;

