"""Pedidos de aprovação humana para ações que GRAVAM (migração, simulação, ajuste de códigos).

Fluxo:  pendente -> aprovada -> executando -> usada
        pendente -> recusada | expirada        aprovada -> expirada | invalidada

O servidor MCP só CRIA pedidos (solicitar_*) e os CONSOME uma vez (executar_pedido_aprovado).
Quem muda "pendente" para "aprovada" é o script aprovar_migracao.py, rodado pelo usuário num
terminal interativo. Nenhuma ferramenta MCP aprova pedidos.

Cada pedido guarda os parâmetros exatos e um hash deles: se algo mudar entre a aprovação e a
execução (parâmetros, itens, conteúdo dos SQLs), o pedido é recusado.
"""
from __future__ import annotations

import hashlib
import json
import os
import re
import secrets
import time
from datetime import datetime
from pathlib import Path

PASTA = Path(os.environ.get("MCP_APROVACOES") or Path(__file__).resolve().parent / "aprovacoes")
_RE_ID = re.compile(r"^[0-9A-F]{6}$")

PENDENTE, APROVADA, EXECUTANDO, USADA = "pendente", "aprovada", "executando", "usada"
RECUSADA, EXPIRADA, INVALIDADA, INDETERMINADA = "recusada", "expirada", "invalidada", "indeterminada"


class ErroAprovacao(Exception):
    """Mensagem pensada para ser lida pelo Claude e pelo usuário."""


def agora() -> float:
    return time.time()


def iso(ts: float | None) -> str | None:
    return None if ts is None else datetime.fromtimestamp(ts).isoformat(timespec="seconds")


def hash_parametros(parametros: dict) -> str:
    bruto = json.dumps(parametros, sort_keys=True, ensure_ascii=False, separators=(",", ":"))
    return hashlib.sha256(bruto.encode("utf-8")).hexdigest()


def _caminho(pedido_id: str) -> Path:
    pid = (pedido_id or "").strip().upper()
    if not _RE_ID.match(pid):
        raise ErroAprovacao("Código de pedido inválido (esperado 6 caracteres, ex.: A3F09C).")
    return PASTA / f"{pid}.json"


def _gravar(p: dict) -> None:
    PASTA.mkdir(parents=True, exist_ok=True)
    destino = _caminho(p["id"])
    tmp = destino.with_suffix(".tmp")
    tmp.write_text(json.dumps(p, ensure_ascii=False, indent=2), encoding="utf-8")
    os.replace(tmp, destino)


def carregar(pedido_id: str) -> dict:
    caminho = _caminho(pedido_id)
    if not caminho.exists():
        raise ErroAprovacao(f"Pedido {pedido_id.upper()} não existe.")
    p = json.loads(caminho.read_text(encoding="utf-8"))
    if p["estado"] in (PENDENTE, APROVADA) and agora() > p["expira_em"]:
        p["estado"] = EXPIRADA
        _gravar(p)
    return p


def criar(tipo: str, parametros: dict, resumo: dict, validade_minutos: int) -> dict:
    PASTA.mkdir(parents=True, exist_ok=True)
    while True:
        pid = secrets.token_hex(3).upper()
        if not _caminho(pid).exists():
            break
    criado = agora()
    p = {
        "id": pid,
        "tipo": tipo,                       # migracao | ajuste_codigos
        "estado": PENDENTE,
        "criado_em": criado,
        "expira_em": criado + validade_minutos * 60,
        "parametros": parametros,
        "hash": hash_parametros(parametros),
        "resumo": resumo,                   # o que o usuário vê ao aprovar (sem senhas)
        "aprovador": None,
        "aprovada_em": None,
        "resultado": None,
        "motivo": None,
    }
    _gravar(p)
    return p


def listar(estados: tuple[str, ...] | None = None) -> list[dict]:
    if not PASTA.exists():
        return []
    itens = []
    for arq in sorted(PASTA.glob("*.json")):
        try:
            p = carregar(arq.stem)
        except (ErroAprovacao, json.JSONDecodeError, KeyError):
            continue
        if estados is None or p["estado"] in estados:
            itens.append(p)
    return sorted(itens, key=lambda p: p["criado_em"])


# ------------------------------------------------------------ decisão humana
def aprovar(pedido_id: str, aprovador: str) -> dict:
    p = carregar(pedido_id)
    if p["estado"] != PENDENTE:
        raise ErroAprovacao(f"O pedido {p['id']} está '{p['estado']}', não pode ser aprovado.")
    if hash_parametros(p["parametros"]) != p["hash"]:
        p["estado"], p["motivo"] = INVALIDADA, "Parâmetros alterados depois do pedido."
        _gravar(p)
        raise ErroAprovacao("Os parâmetros do pedido foram alterados depois de criado. Peça um novo pedido.")
    p.update(estado=APROVADA, aprovador=aprovador, aprovada_em=agora())
    _gravar(p)
    return p


def recusar(pedido_id: str, quem: str) -> dict:
    p = carregar(pedido_id)
    if p["estado"] not in (PENDENTE, APROVADA):
        raise ErroAprovacao(f"O pedido {p['id']} está '{p['estado']}', não pode ser recusado.")
    p.update(estado=RECUSADA, aprovador=quem, motivo="Recusado pelo usuário.")
    _gravar(p)
    return p


# ------------------------------------------------------------------ execução
def reservar_execucao(pedido_id: str) -> dict:
    """Passa 'aprovada' para 'executando' uma única vez. Qualquer outra situação é recusada."""
    caminho = _caminho(pedido_id)
    trava = caminho.with_suffix(".lock")
    PASTA.mkdir(parents=True, exist_ok=True)
    try:
        fd = os.open(trava, os.O_CREAT | os.O_EXCL | os.O_WRONLY)
    except FileExistsError:
        raise ErroAprovacao("Este pedido já está sendo executado.") from None
    try:
        p = carregar(pedido_id)
        mensagens = {
            PENDENTE: "O usuário ainda NÃO aprovou. Peça que ele rode aprovar.bat e digite a frase de confirmação.",
            EXECUTANDO: "Este pedido já está em execução.",
            USADA: "Este pedido já foi executado (cada aprovação vale uma única vez). Faça um novo pedido.",
            RECUSADA: "O usuário recusou este pedido.",
            EXPIRADA: "O pedido expirou. Faça um novo pedido e peça nova aprovação.",
            INVALIDADA: "O pedido foi invalidado" + (f": {p.get('motivo')}" if p.get("motivo") else "") + ". Faça um novo pedido.",
            INDETERMINADA: "A execução deste pedido ficou indeterminada; confira o migrador antes de qualquer nova ação.",
        }
        if p["estado"] != APROVADA:
            raise ErroAprovacao(mensagens.get(p["estado"], f"Pedido em estado '{p['estado']}'."))
        if hash_parametros(p["parametros"]) != p["hash"]:
            p["estado"], p["motivo"] = INVALIDADA, "Parâmetros alterados depois da aprovação."
            _gravar(p)
            raise ErroAprovacao("Os parâmetros foram alterados depois da aprovação. Faça um novo pedido.")
        p["estado"] = EXECUTANDO
        _gravar(p)
        return p
    finally:
        os.close(fd)
        try:
            os.remove(trava)
        except OSError:
            pass


def _mudar(pedido_id: str, estado: str, **campos) -> dict:
    p = carregar(pedido_id)
    p["estado"] = estado
    p.update(campos)
    _gravar(p)
    return p


def concluir(pedido_id: str, resultado: dict) -> dict:
    return _mudar(pedido_id, USADA, resultado=resultado)


def liberar(pedido_id: str) -> dict:
    """Só quando se TEM CERTEZA de que nada começou (ex.: o migrador estava fechado)."""
    return _mudar(pedido_id, APROVADA)


def invalidar(pedido_id: str, motivo: str) -> dict:
    return _mudar(pedido_id, INVALIDADA, motivo=motivo)


def marcar_indeterminada(pedido_id: str, motivo: str) -> dict:
    return _mudar(pedido_id, INDETERMINADA, motivo=motivo)

arquivos.servidor_mcp/aprovar_migracao.py:
"""Aprovação HUMANA dos pedidos do MCP (migração, simulação e ajuste de códigos).

Rode num terminal interativo, pelo usuário:   aprovar.bat [CODIGO]

O Claude não tem como executar isto: o script exige um terminal interativo (teclado de verdade)
e uma frase de confirmação digitada por você. Cada aprovação vale para UM pedido, UMA execução.
"""
from __future__ import annotations

import argparse
import getpass
import sys

import aprovacoes


def mostrar(p: dict, saida=print) -> None:
    r = p["resumo"]
    barra = "=" * 72
    saida(barra)
    saida(f" PEDIDO {p['id']}  —  {r['titulo']}")
    if r.get("real"):
        saida(" >>> ESTE PEDIDO GRAVA NO BANCO DE DESTINO <<<")
    saida(barra)
    saida(f" Criado : {aprovacoes.iso(p['criado_em'])}    Vale até: {aprovacoes.iso(p['expira_em'])}")
    if "origem" in r:
        o = r["origem"]
        saida(f" ORIGEM : {o['nome']} ({o['tipo']})  {o['servidor']}  banco {o['banco']}")
    d = r["destino"]
    saida(f" DESTINO: {d['nome']}  {d['servidor']}  banco {d['banco']}  (usuário {d['usuario']})")
    saida("")
    saida(" Itens pedidos:")
    for i in r["itens_escolhidos"]:
        saida(f"   - {i['id']}  {i['nome']}")
        if i.get("descricao"):
            saida(f"       {i['descricao']}")
    if r.get("itens_automaticos"):
        saida("")
        saida(" Itens AUTOMÁTICOS que entram junto (não foram escolhidos, o migrador os inclui):")
        for i in r["itens_automaticos"]:
            saida(f"   - {i['id']}  {i['nome']}")
            if i.get("descricao"):
                saida(f"       {i['descricao'][:400]}")
    saida("")
    saida(f" Etapas no total: {r.get('etapas_total')}")
    if r.get("opcoes"):
        saida(" Opções: " + ", ".join(f"{k}={'sim' if v else 'não'}" for k, v in r["opcoes"].items()))
    if r.get("arquivos_de_codigos"):
        for k, v in r["arquivos_de_codigos"].items():
            saida(f" Arquivo ({k}): {v}")
    if r.get("previa"):
        saida(f" Prévia: {r['previa']}")
    if r.get("avisos"):
        saida("")
        saida(" ATENÇÃO:")
        for a in r["avisos"]:
            saida(f"   * {a}")
    saida(barra)


def aprovar_interativo(pedido_id: str, entrada=input, saida=print) -> int:
    p = aprovacoes.carregar(pedido_id)
    if p["estado"] != aprovacoes.PENDENTE:
        saida(f"O pedido {p['id']} está '{p['estado']}': não há o que aprovar.")
        return 1
    mostrar(p, saida)
    frase = p["resumo"]["frase_confirmacao"]
    resposta = entrada(f'Para APROVAR digite exatamente  {frase}  (ENTER para cancelar): ').strip()
    if not resposta:
        saida("Cancelado. Nada foi aprovado.")
        return 1
    if resposta != frase:
        saida("A frase não confere. Nada foi aprovado.")
        return 1
    aprovacoes.aprovar(p["id"], getpass.getuser())
    saida(f"APROVADO. Avise o Claude para executar o pedido {p['id']} (vale uma única vez, até {aprovacoes.iso(p['expira_em'])}).")
    return 0


def listar_pendentes(saida=print) -> list[dict]:
    pend = aprovacoes.listar((aprovacoes.PENDENTE,))
    if not pend:
        saida("Nenhum pedido pendente.")
    for p in pend:
        saida(f"  {p['id']}  {p['resumo']['titulo']}  (vale até {aprovacoes.iso(p['expira_em'])})")
    return pend


def main(argv: list[str] | None = None, entrada=input, saida=print, interativo: bool | None = None) -> int:
    ap = argparse.ArgumentParser(description="Aprova ou recusa pedidos do MCP do migrador.")
    ap.add_argument("pedido", nargs="?", help="código do pedido (ex.: A3F09C); sem ele, lista os pendentes")
    ap.add_argument("--recusar", action="store_true", help="recusa o pedido em vez de aprovar")
    args = ap.parse_args(argv)
    try:
        if args.recusar and args.pedido:
            aprovacoes.recusar(args.pedido, getpass.getuser())
            saida(f"Pedido {args.pedido.upper()} recusado.")
            return 0
        if interativo is None:
            interativo = sys.stdin.isatty() and sys.stdout.isatty()
        if not args.pedido:
            pend = listar_pendentes(saida)
            if not pend or not interativo:
                return 0
            args.pedido = entrada("Código do pedido a analisar (ENTER para sair): ").strip()
            if not args.pedido:
                return 0
        if not interativo:
            saida("Aprovar só funciona num terminal interativo, digitado por uma pessoa. Abra o terminal e rode aprovar.bat.")
            return 2
        return aprovar_interativo(args.pedido, entrada, saida)
    except aprovacoes.ErroAprovacao as e:
        saida(f"Erro: {e}")
        return 1


if __name__ == "__main__":
    sys.exit(main())

arquivos.servidor_mcp/conexoes.py:
"""Configuração e conexão com Firebird e SQL Server.

Senhas NUNCA ficam no arquivo de configuração: o JSON só guarda o NOME da variável
de ambiente (senha_env). Os drivers são importados só quando necessários, então quem
usa apenas Firebird não precisa do pyodbc (e vice-versa).
"""
from __future__ import annotations

import json
import os
from pathlib import Path

PASTA = Path(__file__).resolve().parent
TIPOS = ("firebird", "sqlserver", "postgres")
USOS = ("leitura", "migracao")

PADROES = {
    "limite_linhas_padrao": 200,
    "limite_linhas_maximo": 1000,
    "timeout_segundos": 30,
    "mascarar_colunas": ["SENHA", "PASSWORD", "PWD", "TOKEN", "SECRET", "CHAVE_API"],
    # --- migração (aprovação humana) ---
    "app_url": "http://127.0.0.1:8020",       # migrador em execução (só endereço local)
    "aprovacao_validade_minutos": 15,
    "max_itens_por_aprovacao": 1,             # 1 = uma etapa por aprovação
}


class ErroConfig(Exception):
    pass


def caminho_config() -> Path:
    return Path(os.environ.get("MCP_BANCOS_CONFIG") or PASTA / "conexoes.json")


def carregar_config(caminho: Path | None = None) -> dict:
    caminho = caminho or caminho_config()
    if not caminho.exists():
        raise ErroConfig(
            f"Arquivo de configuração não encontrado: {caminho}. "
            "Copie conexoes.exemplo.json para conexoes.json e ajuste."
        )
    try:
        dados = json.loads(caminho.read_text(encoding="utf-8-sig"))
    except json.JSONDecodeError as e:
        raise ErroConfig(f"{caminho.name} não é um JSON válido: {e}") from e
    conexoes = dados.get("conexoes")
    if not isinstance(conexoes, dict) or not conexoes:
        raise ErroConfig("A configuração precisa ter ao menos uma entrada em 'conexoes'.")
    for nome, c in conexoes.items():
        if c.get("tipo") not in TIPOS:
            raise ErroConfig(f"Conexão '{nome}': 'tipo' deve ser um de {TIPOS}.")
        if "senha" in c:
            raise ErroConfig(
                f"Conexão '{nome}': não grave a senha no arquivo. Use 'senha_env' com o nome de uma variável de ambiente."
            )
        if not c.get("banco"):
            raise ErroConfig(f"Conexão '{nome}': falta 'banco'.")
        if c.get("uso", "leitura") not in USOS:
            raise ErroConfig(f"Conexão '{nome}': 'uso' deve ser um de {USOS}.")
    cfg = {**PADROES, **{k: v for k, v in dados.items() if k != "conexoes"}}
    cfg["conexoes"] = conexoes
    cfg["limite_linhas_maximo"] = max(1, int(cfg["limite_linhas_maximo"]))
    cfg["limite_linhas_padrao"] = min(max(1, int(cfg["limite_linhas_padrao"])), cfg["limite_linhas_maximo"])
    cfg["aprovacao_validade_minutos"] = min(max(1, int(cfg["aprovacao_validade_minutos"])), 240)
    cfg["max_itens_por_aprovacao"] = max(1, int(cfg["max_itens_por_aprovacao"]))
    return cfg


def senha_de(nome: str, c: dict) -> str:
    """Lê a senha da variável de ambiente indicada em 'senha_env'."""
    var = c.get("senha_env")
    if not var:
        raise ErroConfig(f"Conexão '{nome}': falta 'senha_env' (nome da variável de ambiente com a senha).")
    valor = os.environ.get(var)
    if valor is None:
        raise ErroConfig(f"Conexão '{nome}': a variável de ambiente {var} não está definida.")
    return valor


# ---------------------------------------------------------------- Firebird
_fb_api_carregada = False


def _conectar_firebird(nome: str, c: dict):
    global _fb_api_carregada
    import fdb  # noqa: WPS433 (import tardio de propósito)

    lib = c.get("fbclient") or os.environ.get("MCP_FBCLIENT")
    if lib and not _fb_api_carregada:
        fdb.load_api(lib)
        _fb_api_carregada = True
    return fdb.connect(
        host=c.get("host", "localhost"),
        port=int(c.get("porta", 3050)),
        database=c["banco"],
        user=c.get("usuario", "SYSDBA"),
        password=senha_de(nome, c),
        charset=c.get("charset", "WIN1252"),
        isolation_level=fdb.ISOLATION_LEVEL_READ_COMMITED_RO,  # transação somente leitura
    )


# --------------------------------------------------------------- SQL Server
def _escapar_odbc(valor: str) -> str:
    return "{" + str(valor).replace("}", "}}") + "}"


def _conectar_sqlserver(nome: str, c: dict, timeout: int):
    import pyodbc

    driver = c.get("driver")
    if not driver:
        instalados = [d for d in pyodbc.drivers() if "SQL Server" in d]
        preferidos = [d for d in instalados if "ODBC Driver" in d]
        if not instalados:
            raise ErroConfig("Nenhum driver ODBC do SQL Server instalado. Instale o 'ODBC Driver 17/18 for SQL Server'.")
        driver = sorted(preferidos or instalados)[-1]
    servidor = c.get("host", "localhost")
    if c.get("porta"):
        servidor = f"{servidor},{int(c['porta'])}"
    partes = [f"DRIVER={_escapar_odbc(driver)}", f"SERVER={servidor}", f"DATABASE={_escapar_odbc(c['banco'])}"]
    if c.get("autenticacao") == "windows":
        partes.append("Trusted_Connection=yes")
    else:
        partes += [f"UID={_escapar_odbc(c.get('usuario', ''))}", f"PWD={_escapar_odbc(senha_de(nome, c))}"]
    if c.get("confiar_certificado"):
        partes.append("TrustServerCertificate=yes")
    partes.append("ApplicationIntent=ReadOnly")
    conn = pyodbc.connect(";".join(partes), timeout=timeout, autocommit=False)
    conn.timeout = timeout  # tempo máximo por consulta
    return conn


# --------------------------------------------------------------- PostgreSQL
def _conectar_postgres(nome: str, c: dict, timeout: int):
    import psycopg

    con = psycopg.connect(
        host=c.get("host", "localhost"),
        port=int(c.get("porta", 5432)),
        dbname=c["banco"],
        user=c.get("usuario", "postgres"),
        password=senha_de(nome, c),
        connect_timeout=10,
        application_name="mcp_migrador_leitura",
        # duas travas: o servidor recusa escrita e a consulta tem tempo máximo
        options=f"-c default_transaction_read_only=on -c statement_timeout={int(timeout) * 1000}",
    )
    con.read_only = True
    return con


def conectar(nome: str, c: dict, timeout: int):
    if c["tipo"] == "firebird":
        return _conectar_firebird(nome, c)
    if c["tipo"] == "postgres":
        return _conectar_postgres(nome, c, timeout)
    return _conectar_sqlserver(nome, c, timeout)

